mapper.update:
UPDATE USER_TBL
SET USER_TYPE = (
    SELECT REQUEST_TYPE
    FROM REQUEST_PERMISSION
    WHERE REQUEST_NO = #{requestNo}
)
WHERE USER_NO = (
    SELECT USER_NO
    FROM REQUEST_PERMISSION
    WHERE REQUEST_NO = #{requestNo}
)

UPDATE REQUEST_PERMISSION
SET REQUEST_STATUS = '반려',
    UPDATED_AT = SYSTIMESTAMP,
    PROCESSED_AT = SYSTIMESTAMP,
    REJECT_REASON = #{rejectReason}
WHERE REQUEST_NO = #{requestNo}
